import { createProject, nextJob, acceptResponse } from '../src/engine.js';

export const auditOK = () => ({ pov_consistent: true, no_new_events: true, ground_truth_consistent: true, clues_supported: true, notes: ['Dữ liệu minh họa viết sẵn để kiểm tra luồng; chưa đánh giá chất lượng sinh truyện của ChatGPT.'] });
export const emptyReader = () => ({ facts: [], clues: [], interpretations: [], answers: [] });
export function simulation(project, job, { actor = 'quan', witnesses = ['quan'], title = 'Cảnh kiểm tra', outcome = 'Nhân vật hỏi nhưng chưa nhận được câu trả lời.', discoveries = [], reveals = [], interpretations = [], event = null } = {}) {
  return structuredClone({ exchange_id: job.id, revision: job.revision, scene_number: job.scene_number, kind: 'simulation',
    scene: { title, location: project.world.location, time: `20:${String(10 + job.scene_number * 3).padStart(2, '0')}`, atmosphere: 'Tiếng mưa và sự do dự giữa những người đang giữ các phần khác nhau của hồ sơ.', pressure: 50 + job.scene_number * 4, ended: true, end_reason: 'Thông tin mới khiến cuộc điều tra chuyển pha.', pov_id: actor, next_actor_id: null },
    turns: [{ actor_id: actor, thought: 'Tôi cần kiểm tra điều vừa nghe trước khi tin nó.', intention: 'Tìm căn cứ và bảo vệ điều mình coi trọng.', mood: { fear: 35, anger: 40, hope: 45, guilt: 30 }, action: 'Tôi yêu cầu kiểm tra và đối chiếu dấu vết.', outcome, witnesses, new_facts: [], reveals, clue_discoveries: discoveries, interpretation_updates: interpretations, belief_updates: [], status_updates: [], trust_updates: [], world_event: event }] });
}
export function proseResponse(project, job, prose, updates = emptyReader()) {
  const s = project.scenes.at(-1);
  return structuredClone({ exchange_id: job.id, revision: job.revision, scene_number: job.scene_number, kind: 'narration', pov_id: s.pov_id, prose, summary: 'Bản thảo minh họa từ fixture viết sẵn.', used_turn_ids: s.turns.filter(t => t.witnesses.includes(s.pov_id) || t.world_event?.witnesses.includes(s.pov_id)).map(t => t.id), reader_updates: updates, editorial_check: auditOK() });
}
const discover = (clue_id, by, excerpt) => ({ clue_id, by, excerpt });
const reveal = (fact_id, to, evidence_clue_ids, excerpt) => ({ fact_id, to, evidence_clue_ids, source_character_id: null, excerpt });
const quote = (key, id, excerpt) => ({ [key]: id, excerpt });

