export function runCaseExample(onStep = () => {}) {
  const project = createProject({ name: '[Minh họa viết sẵn] Hồ sơ dưới cơn mưa', preset_id: 'rain-case', config: { max_scenes: 6, batch_size: 1 } });
  project.fixture_notice = 'Sáu cảnh và câu trả lời viết sẵn để kiểm tra cơ chế. Không phải kết quả chạy ChatGPT, không phải kịch bản bắt buộc của preset.';
  for (const data of caseScenes) {
    let job = nextJob(project), response = simulation(project, job, data.sim);
    if (response.turns[0].actor_id === 'lam') response.turns[0].thought = 'Dòng chữ ấy do tôi xóa để tránh bị truy trách nhiệm. Họ đang nhìn đúng mốc tôi muốn giấu.';
    acceptResponse(project, job.id, JSON.stringify(response)); onStep(project, response);
    job = nextJob(project); response = proseResponse(project, job, data.prose, data.updates);
    acceptResponse(project, job.id, JSON.stringify(response)); onStep(project, response);
  }
  return project;
}
